const draft = reactive({ periode: 'Live', sumber: '', cabang: '' })

const ctx = reactive({
	scope: 'all',
	pic_collector: null,
	nama_collector: null,
	cabang_collection: null,
	periods: [{ value: 'Live', label: 'Live' }],
	branches: [],
	buckets: [],
	sources: ['KSP', 'JG'],
})

const result = ref(null)

const scope = computed(() => ctx.scope)
const rows = computed(() => result.value?.data || [])
const totals = computed(() => result.value?.totals || {})
const comparison = computed(() => result.value?.comparison || {})
const statusMeta = computed(() => result.value?.status_meta || [])
const isCurrency = computed(() => !!result.value?.is_currency)
const milestone = computed(() =>
	result.value?.bucket === 'C0' && result.value?.milestone?.period
		? result.value.milestone
		: null,
)

// Field Coll hanya menerima bucket yang benar-benar dipegangnya, jadi chip-nya
// mengikuti daftar dari server — BUCKETS di atas cuma cadangan sebelum context
// selesai dimuat.
const availableBuckets = computed(() => (ctx.buckets.length ? ctx.buckets : BUCKETS))

const modeLabel = computed(
	() => MODES.find((m) => m.value === realisasi.value)?.label || realisasi.value,
)
const periodeLabel = computed(
	() => ctx.periods.find((p) => p.value === filters.periode)?.label || filters.periode,
)
const subtitle = computed(() =>
	scope.value === 'self' ? 'Capaian penagihan Anda' : 'Capaian penagihan seluruh collector',
)

const activeFilterCount = computed(() => {
	let n = 0
	if (filters.periode !== 'Live') n++
	if (filters.sumber) n++
	if (filters.cabang) n++
	return n
})

// Dua basis milestone (hari kerja & hari kalender) — yang datanya belum ada
// dilewati, bukan ditampilkan kosong.
const milestoneBases = computed(() => {
	const m = milestone.value
	if (!m) return []
	return [
		{ key: 'working', label: 'Hari Kerja', ...(m.working_days || {}) },
		{ key: 'calendar', label: 'Hari Kalender', ...(m.calendar_days || {}) },
	].filter((b) => b.available)
})

const visibleRows = computed(() => {
	const q = search.value.trim().toLowerCase()
	const list = q
		? rows.value.filter((r) => (r.pic_collector || '').toLowerCase().includes(q))
		: [...rows.value]
	if (sortBy.value === 'percentage') {
		list.sort((a, b) => (Number(b.percentage) || 0) - (Number(a.percentage) || 0))
	} else {
		list.sort((a, b) => (Number(b.grand_total) || 0) - (Number(a.grand_total) || 0))
	}
	return list
})

/**
 * Ketiga number card desk diringkas jadi satu objek supaya bisa tampil dalam
 * SATU kartu, sebentuk dengan kartu pencapaian di tab Unit dan Amount.
 * Nilainya tetap datang dari endpoint yang sama, tidak dihitung ulang; hanya
 * persentasenya diturunkan lagi dari target & realisasi agar dua desimalnya
 * benar-benar berarti.
 */
const ringkas = computed(() => {
	const cards = overview.value?.cards || []
	const cari = (label) => cards.find((c) => c.label === label) || {}
	const target = Number(cari('TARGET').value) || 0
	const realisasi = Number(cari('REALISASI').value) || 0
	const persen = cari('%')
	return {
		target,
		realisasi,
		selisih: realisasi - target,
		persentase: target ? (realisasi / target) * 100 : Number(persen.value) || 0,
		comparison_available: persen.comparison_available,
		previous_value: persen.previous_value,
		delta_pp: persen.delta_pp,
		comparison_label: persen.comparison_label,
	}
})
const overviewRingOffset = computed(() => RING - (RING * clampPct(ringkas.value.persentase)) / 100)
const penerimaanTersedia = computed(() => !!overview.value?.penerimaan_available)
const penerimaanKeterangan = computed(() => {
	if (!penerimaanTersedia.value) return 'Uang masuk se-perusahaan'
	if (penerimaanMode.value !== 'Daily') return 'Uang masuk per bulan'
	const label = penerimaanPeriods.value.find((p) => p.value === penerimaanPeriode.value)?.label
	return label ? `Uang masuk per hari pada ${label}` : 'Uang masuk per hari'
})

// Batang chart: tinggi relatif terhadap nilai terbesar, dan hanya nilai
// terbesar yang diberi label supaya deretan angka tidak saling menimpa.
const penerimaanBars = computed(() => {
	const labels = penerimaan.value?.labels || []
	const values = penerimaan.value?.values || []
	const max = Math.max(1, ...values.map((v) => Math.abs(Number(v) || 0)))
	return labels.map((label, i) => {
		const value = Number(values[i]) || 0
		return {
			label,
			value,
			puncak: value === max && value > 0,
			height: `${Math.min(100, (Math.max(0, value) / max) * 100)}%`,
		}
	})
})

const ringColor = computed(() => pctColor(totals.value.percentage))
const ringOffset = computed(() => RING - (RING * clampPct(totals.value.percentage)) / 100)

function statusColor(fieldname) {
	return STATUS_COLORS[fieldname] || '#94a3b8'
}

function rankClass(idx) {
	if (idx === 0) return 'bg-ui-surface-amber-100 text-ui-ink-amber-700'
	if (idx === 1) return 'bg-ui-surface-gray-200 text-ui-ink-gray-700'
	if (idx === 2) return 'bg-ui-surface-orange-100 text-ui-ink-orange-700'
	return 'bg-ui-surface-gray-100 text-ui-ink-gray-500'
}

function pacingTextClass(value) {
	const p = Number(value)
	if (!Number.isFinite(p)) return 'text-ui-ink-gray-500'
	if (p >= 100) return 'text-ui-ink-green-600'
	if (p >= 90) return 'text-ui-ink-amber-600'
	return 'text-ui-ink-red-600'
}

function pacingNote(value) {
	const p = Number(value)
	if (!Number.isFinite(p)) return 'Belum bisa dihitung'
	if (p >= 100) return 'Di atas pace'
	if (p >= 90) return 'Mendekati pace'
	return 'Di bawah pace'
}

// Mode yang sedang dilihat menentukan satuannya; helper bersamanya menerima
// flag itu sebagai argumen supaya bisa dipakai komponen lain juga.
function fmtMetric(value) {
	return fmtMetricRaw(value, isCurrency.value)
}

function fmtMetricFull(value) {
	return fmtMetricFullRaw(value, isCurrency.value)
}

function isModeDisabled(mode) {
	return mode === 'Realisasi Amount ++' && bucket.value === BUCKET_TANPA_AMOUNT_PLUS
}

function selectAll() {
	if (view.value === 'all') return
	view.value = 'all'
	loadAll()
}

function selectMode(mode) {
	if (isModeDisabled(mode)) return
	const pindahTab = view.value !== 'performance'
	if (!pindahTab && realisasi.value === mode) return
	view.value = 'performance'
	realisasi.value = mode
	loadData()
}

function selectBucket(value) {
	if (bucket.value === value) return
	bucket.value = value
	// CX WO tidak melayani Amount ++ — turunkan ke Amount agar tetap sebanding.
	if (isModeDisabled(realisasi.value)) realisasi.value = 'Realisasi Amount'
	loadData()
}

function toggleSort() {
	sortBy.value = sortBy.value === 'volume' ? 'percentage' : 'volume'
	listPersistence.writePreferences({ sortBy: sortBy.value })
}

function toggleRow(pic) {
	expanded[pic] = !expanded[pic]
}

function openFilter() {
	draft.periode = filters.periode
	draft.sumber = filters.sumber
	draft.cabang = filters.cabang
	showFilter.value = true
}

function resetFilter() {
	draft.periode = 'Live'
	draft.sumber = ''
	draft.cabang = ''
}

function saveSessionState() {
	const isDefault = filters.periode === 'Live' && !filters.sumber && !filters.cabang
	if (isDefault && !search.value) listPersistence.clearSession()
	else listPersistence.writeSession({ filters, search: search.value })
}

function setPenerimaanMode(mode) {
	if (penerimaanMode.value === mode) return
	penerimaanMode.value = mode
	loadPenerimaan()
}

function setPenerimaanPeriode(value) {
	if (penerimaanPeriode.value === value) return
	penerimaanPeriode.value = value
	loadPenerimaan()
}

// Tab All: tiga number card + chart Penerimaan Harian.
async function loadAll() {
	loadingAll.value = true
	try {
		overview.value = await call(API_OVERVIEW, {
			sumber: filters.sumber,
			cabang: filters.cabang,
			periode: filters.periode,
		})
	} catch (e) {
		notifyError(e, 'Gagal memuat ringkasan')
		if (!overview.value && !result.value) fatalError.value = errorText(e)
		loadingAll.value = false
		return
	}
	loadingAll.value = false
	if (!penerimaanTersedia.value) return
	if (!penerimaanPeriods.value.length) await loadPenerimaanOptions()
	await loadPenerimaan()
}

async function loadPenerimaanOptions() {
	try {
		const data = await call(API_PENERIMAAN_OPTIONS)
		penerimaanPeriods.value = data?.periods || []
		penerimaanPeriode.value = data?.default_period || penerimaanPeriods.value[0]?.value || ''
	} catch {
		penerimaanPeriods.value = []
	}
}

async function loadPenerimaan() {
	loadingPenerimaan.value = true
	try {
		penerimaan.value = await call(API_PENERIMAAN_CHART, {
			mode: penerimaanMode.value,
			periode: penerimaanPeriode.value,
			sumber: filters.sumber,
		})
	} catch (e) {
		penerimaan.value = null
		notifyError(e, 'Gagal memuat Penerimaan Harian')
	} finally {
		loadingPenerimaan.value = false
	}
}

async function applyFilter() {
	const periodeBerubah = filters.periode !== draft.periode
	filters.periode = draft.periode
	filters.sumber = draft.sumber
	filters.cabang = draft.cabang
	saveSessionState()
	showFilter.value = false
	if (periodeBerubah) {
		loading.value = true
		try {
			await loadContext()
		} catch (e) {
			notifyError(e, 'Gagal memuat opsi filter')
		}
	}
	await muatTabAktif()
}

function muatTabAktif() {
	return view.value === 'all' ? loadAll() : loadData()
}

// Pesan error Frappe datang sebagai `messages` (list HTML) atau `message`.
function errorText(e) {
	const raw = e?.messages?.join(' ') || e?.message || ''
	const text = String(raw)
		.replace(/<[^>]*>/g, ' ')
		.replace(/\s+/g, ' ')
		.trim()
	return text || 'Anda tidak punya akses ke dashboard ini.'
}

async function loadContext() {
	// Daftar bucket bergantung periode (bucket yang dipegang seorang collector
	// berbeda tiap bulan), jadi periode yang sedang aktif ikut dikirim.
	const data = await call('juragan.api.portal.realisasi_collection.get_dashboard_context', {
		periode: filters.periode,
	})
	if (!data) return
	ctx.scope = data.scope || 'all'
	ctx.pic_collector = data.pic_collector
	ctx.nama_collector = data.nama_collector
	ctx.cabang_collection = data.cabang_collection
	ctx.periods = data.periods?.length ? data.periods : [{ value: 'Live', label: 'Live' }]
	ctx.branches = data.branches || []
	ctx.buckets = data.buckets || []
	ctx.sources = data.sources || ['KSP', 'JG']
	// Bucket yang sedang dipilih bisa saja tidak ada di daftar baru (mis. Field
	// Coll yang bucketnya berubah antar periode) — pindahkan ke yang pertama.
	if (!availableBuckets.value.includes(bucket.value)) {
		bucket.value = availableBuckets.value[0]
		if (isModeDisabled(realisasi.value)) realisasi.value = 'Realisasi Amount'
	}
}

async function loadData() {
	loading.value = true
	try {
		result.value = await call('juragan.api.portal.realisasi_collection.get_performance_list', {
			bucket: bucket.value,
			realisasi: realisasi.value,
			sumber: filters.sumber,
			cabang: filters.cabang,
			periode: filters.periode,
		})
		// Kartu yang terbuka milik daftar sebelumnya — tutup semua agar tidak
		// menampilkan rincian bucket/mode yang sudah tidak berlaku.
		Object.keys(expanded).forEach((key) => delete expanded[key])
	} catch (e) {
		notifyError(e, 'Gagal memuat data realisasi')
		// Belum pernah ada data yang berhasil dimuat → jangan biarkan halaman
		// memperlihatkan angka nol yang terlihat seperti capaian sungguhan.
		if (!result.value) fatalError.value = errorText(e)
	} finally {
		loading.value = false
	}
}

async function reload() {
	if (loading.value || loadingAll.value) return
	await muatTabAktif()
}

onMounted(async () => {
	loading.value = true
	try {
		await refreshCsrfToken()
		const saved = listPersistence.readSession({
			filters: { periode: 'Live', sumber: '', cabang: '' },
			search: '',
		})
		search.value = saved.search
		const prefs = listPersistence.readPreferences({ sortBy: 'volume' })
		if (['volume', 'percentage'].includes(prefs.sortBy)) sortBy.value = prefs.sortBy
		await loadContext()
		const allowedPeriods = ctx.periods.map((item) => item.value)
		if (allowedPeriods.includes(saved.filters.periode)) {
			filters.periode = saved.filters.periode
			if (filters.periode !== 'Live') await loadContext()
		}
		filters.sumber = ctx.sources.includes(saved.filters.sumber) ? saved.filters.sumber : ''
		filters.cabang = ctx.branches.includes(saved.filters.cabang) ? saved.filters.cabang : ''
	} catch (e) {
		// Gagal di sini berarti user tidak berhak / sesi bermasalah: tampilkan
		// pesannya di halaman, jangan biarkan dashboard kosong tanpa penjelasan.
		fatalError.value = errorText(e)
		loading.value = false
		return
	}
	await muatTabAktif()
})

watch(search, saveSessionState)
</script>
